def climbStairs(n):
    prev, cur = 1, 1  # ways to reach steps i-1 and i
    for _ in range(n - 1):
        prev, cur = cur, prev + cur
    return cur

reference_solutions.javascript:
function climbStairs(n) {
  const memo = new Map();
  function ways(k) {
    if (k <= 1) return 1;
    if (memo.has(k)) return memo.get(k);
    const w = ways(k - 1) + ways(k - 2);
    memo.set(k, w);
    return w;
  }
  return ways(n);
}
